// Offline web app (issue #56, ADR-004-CTPY): every page of the production build registers the
// service worker web/dist/sw.js (generated by offline-build.js), which stores the whole build.
// While it stores, a badge at the bottom left counts the files ("Offline: n / m"), then says
// "Offline bereit" for a few seconds; "Offline nicht möglich" (and no more counting) when a file
// can't be stored. The dev pages never do. Imported for its effect by main.js, submodel.js and
// vorlagen.js.
const SHOW_READY = 4000;   // ms

let badge = null, hideTimer = 0, failed = false;
function say(text) {
  if (!badge) {
    badge = Object.assign(document.createElement('div'), { className: 'fl-offline' });
    Object.assign(badge.style, { position: 'fixed', left: '16px', bottom: '16px', zIndex: '10', pointerEvents: 'none',
      padding: '4px 9px', borderRadius: '4px', background: 'rgba(243, 239, 230, 0.92)', color: '#2b2926',
      font: '13px/1.3 system-ui, sans-serif', boxShadow: '0 1px 3px rgba(0, 0, 0, 0.18)' });
    document.body.append(badge);
  }
  clearTimeout(hideTimer);
  badge.textContent = text;
}

if (import.meta.env.PROD && 'serviceWorker' in navigator) {
  navigator.serviceWorker.addEventListener('message', ({ data }) => {
    if (data?.type === 'offline-progress' && !failed) say(`Offline: ${data.done} / ${data.total}`);
    if (data?.type === 'offline-ready' && badge) {                 // only after a download on this page
      say('Offline bereit');
      hideTimer = setTimeout(() => { badge.remove(); badge = null; }, SHOW_READY);
    }
    if (data?.type === 'offline-failed') { failed = true; say('Offline nicht möglich'); }   // stays; the next online load retries
  });
  navigator.serviceWorker.startMessages();
  navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`).catch(() => {});   // blocked: online only
  navigator.storage?.persist?.().catch(() => {});                 // ask the browser not to evict the store
}
